-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Unternehmensformen > GmbH
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Haftung einer GmbH in der IT-Branche auf das Gesellschaftsvermögen beschränkt?', 2, '[{"text": "Ja", "correct": true, "because": "Die GmbH haftet nur mit ihrem Vermögen"}, {"text": "Nein", "correct": false, "because": "Beschränkte Haftung ist ein Merkmal der GmbH"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IT-GmbH ein Mindestkapital von 25.000 Euro einbringen?', 2, '[{"text": "Ja", "correct": true, "because": "Das Mindeststammkapital der GmbH beträgt 25.000 Euro"}, {"text": "Nein", "correct": false, "because": "Mindestkapital ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-GmbH von einer einzelnen Person gegründet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Eine Ein-Person-GmbH ist möglich"}, {"text": "Nein", "correct": false, "because": "Einzelgründung ist zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IT-GmbH ihre Jahresabschlüsse beim Bundesanzeiger veröffentlichen?', 2, '[{"text": "Ja", "correct": true, "because": "GmbHs sind zur Offenlegung verpflichtet"}, {"text": "Nein", "correct": false, "because": "Veröffentlichung ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die GmbH als Unternehmensform für IT-Startups geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Die GmbH bietet Haftungsbeschränkung und Flexibilität"}, {"text": "Nein", "correct": false, "because": "GmbH ist für Startups beliebt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal einer IT-GmbH?', 2, '[{"text": "Beschränkte Haftung", "correct": true, "because": "Haftung ist auf das Gesellschaftsvermögen begrenzt"}, {"text": "Persönliche Haftung", "correct": false, "because": "Das gilt für Einzelunternehmen"}, {"text": "Keine Kapitalanforderung", "correct": false, "because": "Mindestkapital ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mindeststammkapital muss eine IT-GmbH aufbringen?', 3, '[{"text": "25.000 Euro", "correct": true, "because": "Gesetzlich vorgeschrieben für eine GmbH"}, {"text": "10.000 Euro", "correct": false, "because": "Zu niedrig"}, {"text": "50.000 Euro", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer führt die Geschäfte einer IT-GmbH?', 3, '[{"text": "Geschäftsführer", "correct": true, "because": "Geschäftsführer leiten die GmbH"}, {"text": "Gesellschafter", "correct": false, "because": "Gesellschafter sind Eigentümer, nicht zwingend Geschäftsführer"}, {"text": "Aufsichtsrat", "correct": false, "because": "Aufsichtsrat ist bei AGs üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Gründung einer IT-GmbH?', 2, '[{"text": "GmbH-Gesetz (GmbHG)", "correct": true, "because": "Das GmbHG regelt die GmbH"}, {"text": "Handelsgesetzbuch (HGB)", "correct": false, "because": "HGB ergänzt, aber GmbHG ist spezifisch"}, {"text": "BBiG", "correct": false, "because": "BBiG regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil der GmbH als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Beschränkte Haftung", "correct": true, "because": "Schützt das Privatvermögen"}, {"text": "Keine Buchführungspflicht", "correct": false, "because": "GmbH ist buchführungspflichtig"}, {"text": "Keine Kapitalanforderung", "correct": false, "because": "Mindestkapital ist erforderlich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine IT-GmbH?', 4, '[{"text": "Beschränkte Haftung", "correct": true, "because": "Haftung auf Gesellschaftsvermögen begrenzt"}, {"text": "Mindeststammkapital von 25.000 Euro", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Persönliche Haftung der Gesellschafter", "correct": false, "because": "Nicht bei GmbH"}, {"text": "Geschäftsführung durch Geschäftsführer", "correct": true, "because": "Geschäftsführer leiten die GmbH"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die GmbH als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Haftungsbeschränkung", "correct": true, "because": "Schützt das Privatvermögen"}, {"text": "Kapitalbeschaffung durch Anteile", "correct": true, "because": "Gesellschafter können Anteile einbringen"}, {"text": "Keine Buchführungspflicht", "correct": false, "because": "GmbH ist buchführungspflichtig"}, {"text": "Rechtssicherheit durch GmbHG", "correct": true, "because": "Gesetzliche Regelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die GmbH als Unternehmensform für einen IT-Betrieb?', 4, '[{"text": "Hohe Gründungskosten", "correct": true, "because": "Mindestkapital und Notarkosten"}, {"text": "Buchführungspflicht", "correct": true, "because": "GmbH muss bilanzieren"}, {"text": "Persönliche Haftung", "correct": false, "because": "Nicht bei GmbH"}, {"text": "Veröffentlichungspflicht", "correct": true, "because": "Jahresabschlüsse müssen veröffentlicht werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat eine IT-GmbH gemäß dem GmbHG?', 3, '[{"text": "Einbringung des Stammkapitals", "correct": true, "because": "Mindestkapital erforderlich"}, {"text": "Erstellung eines Jahresabschlusses", "correct": true, "because": "Bilanzierungspflicht"}, {"text": "Keine Steuerpflicht", "correct": false, "because": "Steuerpflicht besteht"}, {"text": "Offenlegung beim Bundesanzeiger", "correct": true, "because": "Veröffentlichungspflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die GmbH von einem Einzelunternehmen für einen IT-Betrieb?', 3, '[{"text": "Beschränkte Haftung bei der GmbH", "correct": true, "because": "Einzelunternehmen haftet persönlich"}, {"text": "Mindestkapital bei der GmbH", "correct": true, "because": "Einzelunternehmen hat keine Kapitalanforderung"}, {"text": "Keine Buchführung bei der GmbH", "correct": false, "because": "GmbH ist buchführungspflichtig"}, {"text": "Geschäftsführung bei der GmbH", "correct": true, "because": "Einzelunternehmer führt selbst"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die GmbH haftet nur mit dem Gesellschaftsvermögen. b) Eine IT-GmbH benötigt kein Stammkapital.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine IT-GmbH kann von einer Person gegründet werden. b) Die GmbH muss ihre Jahresabschlüsse veröffentlichen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Ein-Person-GmbH und Veröffentlichungspflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die GmbH bietet Haftungsbeschränkung für IT-Betriebe. b) Geschäftsführer haften persönlich mit ihrem Vermögen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftungsbeschränkung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine IT-GmbH hat ein Mindeststammkapital von 25.000 Euro. b) Die GmbH ist nicht buchführungspflichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mindestkapital ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die GmbH wird durch Geschäftsführer geleitet. b) Gesellschafter haften mit ihrem Privatvermögen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschäftsführer ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

